/* ====== SLA helpers ====== */
function slaHuman(min){ if(min==null) return ''; const a=Math.abs(min); return a>=1440?Math.round(a/1440)+'d':a>=60?Math.round(a/60)+'h':a+'m'; }
function SLABadge({s,label}){ if(!s||s.state==='none') return null;
  const M={met:['var(--green)','var(--greenL)'],breached:['var(--red)','var(--redL)'],due_soon:['var(--amber)','var(--amberL)'],on_track:['var(--accent)','var(--accentL)'],paused:['var(--purple)','var(--purpleL)']};
  const cb=M[s.state]||['var(--t4)','var(--s3)'];
  const txt=s.state==='met'?'Met':s.state==='paused'?'Paused':s.state==='breached'?('Overdue '+slaHuman(s.left)):('Due '+slaHuman(s.left));
  return <span style={{display:'inline-flex',alignItems:'center',gap:5,fontSize:12,fontWeight:600,color:cb[0],background:cb[1],padding:'2px 8px',borderRadius:6,whiteSpace:'nowrap'}}>{label?label+': ':''}{txt}</span>;
}

