const OPSH_ROLLOUT_ITEMS = (st) => st.parts.reduce((a, p) => a.concat(p[1]), []);
const OPSH_ROLLOUT_LEVEL = { req: ['REQUIRED', 'var(--red)', 'var(--redL)'], rec: ['RECOMMENDED', '#6b541a', '#fbf3e0'], opt: ['OPTIONAL', 'var(--t3)', 'var(--s3)'] };
