        <SpStat attr="iptop" label="Top address share" value={ips.ips.length?ips.ips[0].share+'%':'—'} band={!ips.ips.length?'none':ips.ips[0].share>=30?'crit':ips.ips[0].share>=15?'high':ips.ips[0].share>=5?'busy':'good'} sub={ips.ips.length?ips.ips[0].ip:''}/>
